    sounds[0].rate(random(0,3));
  }

  y += h;
  // Gong
  if (frameCount % floor(beat*12) == 1) {
    sounds[1].play();
  }

    y += h;
  // Bamboo
  if (frameCount % 80 == 10) {
    sounds[3].play();
    sounds[3].rate(random(0,1));
  }

  y += h;
  //String
  if (frameCount % beat == sb) {
    sounds[5].play();
    sb--;
  }

  y += h;
  // Kalim
  if (frameCount % 100 == 20) {
    sounds[4].play();
